import java.util.Arrays;

public class CoinChange {
    public int coinChange(int[] coins, int amount) {
        int max = amount + 1; // 哨兵值：不可能达到的大数
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, max);
        dp[0] = 0; // 凑出 0 元不需要硬币

        for (int coin : coins) {
            for (int a = coin; a <= amount; a++) { // 正向遍历：完全背包
                dp[a] = Math.min(dp[a], dp[a - coin] + 1);
            }
        }
        return dp[amount] > amount ? -1 : dp[amount];
    }

    public static void main(String[] args) {
        CoinChange sol = new CoinChange();
        System.out.println(sol.coinChange(new int[]{1, 2, 5}, 11)); // 3
        System.out.println(sol.coinChange(new int[]{2}, 3));         // -1
        System.out.println(sol.coinChange(new int[]{1, 3, 4}, 6));  // 2（贪心给 3，DP 给 2）
        System.out.println(sol.coinChange(new int[]{1}, 0));        // 0
    }
}

import java.util.Arrays;

public class CoinChangeMemo {
    private int[] memo;

    public int coinChange(int[] coins, int amount) {
        memo = new int[amount + 1];
        Arrays.fill(memo, -2); // -2 表示未计算
        return helper(coins, amount);
    }

    private int helper(int[] coins, int amount) {
        if (amount == 0) return 0;
        if (amount < 0) return -1;
        if (memo[amount] != -2) return memo[amount];

        int min = Integer.MAX_VALUE;
        for (int coin : coins) {
            int res = helper(coins, amount - coin);
            if (res >= 0) {
                min = Math.min(min, res + 1);
            }
        }
        memo[amount] = (min == Integer.MAX_VALUE) ? -1 : min;
        return memo[amount];
    }
}
